#include <iostream>

using std::cout;
using std::endl;
using std::cin;

int main()
{
    int iNumber;
    cout << "Input Number: ";
    cin >> iNumber;

    switch (iNumber)
    {
    case 0:
        cout << "영" << endl;
        break;
    case 1:
        cout << "일" << endl;
        break;
    case 2:
    case 3:
        cout << "이 또는 삼" << endl;
        break;
    default:
        cout << "그 외의 숫자입니다." << endl;
        break;
    }

    return 0;
}

