#include <iostream>

using std::cout;
using std::endl;
using std::cin;

int main()
{
    int kor, eng, math;

    cout << "국어 점수 입력: ";
    cin >> kor;
    cout << "영어 점수 입력: ";
    cin >> eng;
    cout << "수학 점수 입력: ";
    cin >> math;

    int avg = (kor + eng + math) / 3;

    cout << "평균: " << avg << ", 등급: ";

    switch (avg / 10)
    {
    case 10:
    case 9:
        cout << "A" << endl;
        break;
    case 8:
        cout << "B" << endl;
        break;
    case 7:
        cout << "C" << endl;
        break;
    default:
        cout << "F" << endl;
        break;
    }

    return 0;
}
